class Solution:
 def selfDividingNumbers(self,left,right):
  out=[]
  for x in range(left,right+1):
   n=x;ok=True
   while n:
    d=n%10
    if d==0 or x%d:ok=False;break
    n//=10
   if ok:out.append(x)
  return out

class Solution:
 def floodFill(self,image,sr,sc,color):
  old=image[sr][sc]
  if old==color:return image
  m,n=len(image),len(image[0]);stack=[(sr,sc)];image[sr][sc]=color
  while stack:
   r,c=stack.pop()
   for x,y in ((r+1,c),(r-1,c),(r,c+1),(r,c-1)):
    if 0<=x<m and 0<=y<n and image[x][y]==old:image[x][y]=color;stack.append((x,y))
  return image

class Solution:
 def nextGreatestLetter(self,letters,target):
  lo=0;hi=len(letters)
  while lo<hi:
   mid=(lo+hi)//2
   if letters[mid]<=target:lo=mid+1
   else:hi=mid
  return letters[lo] if lo<len(letters) else letters[0]

class Solution:
 def minCostClimbingStairs(self,cost):
  a=b=0
  for i in range(2,len(cost)+1):a,b=b,min(a+cost[i-2],b+cost[i-1])
  return b

class Solution:
 def dominantIndex(self,nums):
  if len(nums)==1:return 0
  largest=max(nums);i=nums.index(largest);second=max(nums[:i]+nums[i+1:])
  return i if largest>=2*second else -1

from collections import Counter
class Solution:
 def shortestCompletingWord(self,licensePlate,words):
  need=Counter(c.lower() for c in licensePlate if c.isalpha())
  ans=None
  for w in words:
   have=Counter(w)
   if all(have[c]>=n for c,n in need.items()) and (ans is None or len(w)<len(ans)):ans=w
  return ans

class Solution:
 def countPrimeSetBits(self,left,right):
  primes={2,3,5,7,11,13,17,19}
  return sum(n.bit_count() in primes for n in range(left,right+1))

class Solution:
 def isToeplitzMatrix(self,matrix):
  return all(matrix[r][c]==matrix[r-1][c-1] for r in range(1,len(matrix)) for c in range(1,len(matrix[0])))

class Solution:
 def numJewelsInStones(self,jewels,stones):
  j=set(jewels);return sum(c in j for c in stones)

class Solution:
 def minDiffInBST(self,root):
  vals=[]
  def dfs(n):
   if n:dfs(n.left);vals.append(n.val);dfs(n.right)
  dfs(root);return min(b-a for a,b in zip(vals,vals[1:]))
